test("readablePaths confinement", async () => {
  const root = fixture();
  const tools = createAgentTools({
    root,
    readablePaths: ["subdir"]
  });

  // Test list_files
  const listRoot = JSON.parse(tools.execute({ action: "list_files", args: { path: "." } }));
  ok(listRoot.error.includes("path is outside declared readable paths"));

  const listSub = JSON.parse(tools.execute({ action: "list_files", args: { path: "subdir" } }));
  deepStrictEqual(listSub.files, ["subdir/b.txt"]);

  // Test search
  const searchRoot = JSON.parse(tools.execute({ action: "search", args: { query: "hello" } }));
  ok(searchRoot.error.includes("path is outside declared readable paths"));

  const searchSub = JSON.parse(tools.execute({ action: "search", args: { query: "world" } }));
  strictEqual(searchSub.hits[0].path, "subdir/b.txt");

  // Test read
